                <td data-label="Incident"><span class="report-table__title">{{ $row['incident_title'] }}</span><span class="report-table__sub">{{ $row['type'] === 'aar' ? 'Station activity record' : 'Station incident record' }}</span></td>
                <td data-label="Investigator">{{ $row['investigator'] }}</td><td data-label="Status"><span class="report-status report-status--{{ $row['status'] }}">{{ str_replace('_',' ',$row['status']) }}</span><br><span class="report-review-chip report-review-chip--{{ $row['review_status'] ?? 'submitted' }}">{{ $row['review_status_label'] ?? 'Submitted' }}</span></td>
                @if($reportType==='all')<td data-label="Filed">{{ $row['created_at']?->format('M d, Y g:i A')??'Not recorded' }}</td>
                @elseif($reportType==='spot')<td data-label="Owner / occupancy"><span class="report-table__title">{{ $row['owner'] }}</span><span class="report-table__sub">{{ ucfirst($row['occupancy']) }}</span></td><td data-label="Fire timeline"><span class="report-table__title">{{ $row['fire_started']?->format('M d, Y g:i A')??'Not recorded' }}</span><span class="report-table__sub">Out: {{ $row['fire_out']?->format('M d, Y g:i A')??'Not recorded' }}</span></td><td data-label="Damage / area"><span class="report-table__title">₱{{ number_format($row['estimated_damage'],0) }}</span><span class="report-table__sub">{{ number_format($row['estimated_area'],1) }} sqm</span></td><td data-label="Casualties">{{ number_format($row['casualties']) }}</td>
