                <td data-label="Actions"><div class="report-row-actions"><button type="button" class="report-icon-button" data-report-action="view" data-report-key="{{ $row['type'] }}:{{ $row['id'] }}" aria-label="View report" title="View"><i class="fa-regular fa-eye"></i></button>@if($row['type'] !== 'aar')<button type="button" class="report-icon-button" data-report-action="edit" data-report-key="{{ $row['type'] }}:{{ $row['id'] }}" aria-label="Edit report" title="Edit"><i class="fa-regular fa-pen-to-square"></i></button>@endif @if(($row['review_status'] ?? 'submitted') !== 'approved')<button type="button" class="report-icon-button report-icon-button--approve" data-report-action="approve" data-report-key="{{ $row['type'] }}:{{ $row['id'] }}" aria-label="Approve report" title="Approve"><i class="fa-solid fa-check"></i></button>@endif @if(($row['review_status'] ?? 'submitted') !== 'rejected' && ($row['review_status'] ?? 'submitted') !== 'changes_requested' && !($row['type'] === 'aar' && ($row['review_status'] ?? 'submitted') === 'approved'))<button type="button" class="report-icon-button report-icon-button--reject" data-report-action="reject" data-report-key="{{ $row['type'] }}:{{ $row['id'] }}" aria-label="{{ $row['type'] === 'aar' ? 'Request changes' : 'Reject report' }}" title="{{ $row['type'] === 'aar' ? 'Request changes' : 'Reject' }}"><i class="fa-solid fa-xmark"></i></button>@endif @if($row['type'] !== 'aar')<button type="button" class="report-icon-button report-icon-button--danger" data-report-action="delete" data-report-key="{{ $row['type'] }}:{{ $row['id'] }}" aria-label="Delete report" title="Delete"><i class="fa-regular fa-trash-can"></i></button>@endif</div></td>
