<script>
document.addEventListener('DOMContentLoaded',()=>{
    const sidebar=document.getElementById('sidebar'),backdrop=document.getElementById('sidebarBackdrop');
    document.getElementById('openSidebar')?.addEventListener('click',()=>{sidebar?.classList.add('open');backdrop?.classList.remove('hidden')});
    backdrop?.addEventListener('click',()=>{sidebar?.classList.remove('open');backdrop.classList.add('hidden')});
    document.getElementById('type')?.addEventListener('change',event=>{document.getElementById('status').value='';event.target.form.requestSubmit()});

    const modal=document.getElementById('executiveReportModal'),body=document.getElementById('executiveReportModalBody'),footer=document.getElementById('executiveReportModalFooter'),title=document.getElementById('executiveReportModalTitle'),eyebrow=document.getElementById('executiveReportModalEyebrow'),closeButton=document.getElementById('executiveReportModalClose'),csrf=document.querySelector('meta[name="csrf-token"]')?.content,reviewerName=@json(auth()->user()->full_name);
    let activeReport=null,opener=null;
    const fieldSets={
        spot:['memorandum_for','place_of_occurrence','involved_structure','establishment_name','occupant','owner','occupancy','estimated_damage','estimated_area','dead','injured','highest_alarm_level','affected_establishments_count','fire_started','fire_out','description','fatality_details','details_of_investigation','disposition'],
        progress:['memorandum_for','mission_order_number','mission_order_date','responsible_arson','fire_cause','facts_of_case','disposition','report_completed_at'],
        final:['memorandum_for','office_address','alarm_at','establishment_burned','fire_victims','origin_of_fire','cause_of_fire','exact_address','total_damage','facts_of_case','discussion','findings','recommendation','report_completed_at'],
        aar:['activity_title','activity_type','activity_date','activity_location','participants','deployed_resources','memorandum_for','report_completed_at','references','background','significance','activity_details','issues_challenges','discussion_assessment','recommendations']
    };
    const labels={memorandum_for:'Memorandum for',place_of_occurrence:'Place of occurrence',involved_structure:'Involved structure',establishment_name:'Establishment name',occupant:'Occupant',owner:'Owner',occupancy:'Occupancy',estimated_damage:'Estimated damage',estimated_area:'Estimated area (sqm)',dead:'Fatalities',injured:'Injured',highest_alarm_level:'Highest alarm level',affected_establishments_count:'Affected establishments',fire_started:'Fire started',fire_out:'Fire out',description:'Description',fatality_details:'Fatality details',details_of_investigation:'Investigation details',disposition:'Disposition',mission_order_number:'Mission order number',mission_order_date:'Mission order date',responsible_arson:'Arson finding',fire_cause:'Fire cause',facts_of_case:'Facts of case',report_completed_at:'Report completed',office_address:'Office address',alarm_at:'Alarm time',establishment_burned:'Establishment burned',fire_victims:'Fire victims',origin_of_fire:'Origin of fire',cause_of_fire:'Cause of fire',exact_address:'Exact address',total_damage:'Total damage',discussion:'Discussion',findings:'Findings',recommendation:'Recommendation',activity_title:'Activity title',activity_type:'Activity type',activity_date:'Activity date',activity_location:'Activity location',participants:'Participants',deployed_resources:'Deployed resources',references:'References',background:'Background',significance:'Significance',activity_details:'Activity details',issues_challenges:'Issues / challenges',discussion_assessment:'Discussion / assessment',recommendations:'Recommendations'};
    const longFields=new Set(['description','fatality_details','details_of_investigation','disposition','facts_of_case','office_address','fire_victims','origin_of_fire','cause_of_fire','discussion','findings','recommendation','participants','deployed_resources','references','background','significance','activity_details','issues_challenges','discussion_assessment','recommendations']);
    const dateFields=new Set(['mission_order_date','activity_date']);
    const dateTimeFields=new Set(['fire_started','fire_out','report_completed_at','alarm_at']);
    const numberFields=new Set(['estimated_damage','estimated_area','dead','injured','affected_establishments_count','total_damage']);
    const requiredFields=new Set(['fire_cause','exact_address','total_damage']);
    const escapeHtml=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[char]));
    const displayValue=value=>value===null||value===undefined||value===''?'Not recorded':String(value).replace('T',' ').replace(/\.000000Z$|Z$/,'');
    const reviewStatus=report=>report.review_status||'submitted';
    const reviewLabel=report=>report.review_status_label||reviewStatus(report).replaceAll('_',' ');
    const inputValue=(value,type)=>{if(!value)return'';const string=String(value);return type==='datetime-local'?string.slice(0,16):type==='date'?string.slice(0,10):string};
    const reportName=report=>report.type==='aar'?'After Activity Report':`${report.type.charAt(0).toUpperCase()+report.type.slice(1)} investigation report`;
    const downloadUrl=report=>report.download_url||(report.type==='spot'?`/station-admin/spot-reports/${report.id}/sir.docx`:report.type==='progress'?`/station-admin/progress-reports/${report.id}/pir.docx`:`/station-admin/final-reports/${report.id}/fir.docx`);
    const setError=message=>{const box=document.getElementById('executiveReportModalError');if(!box)return;box.textContent=message||'';box.classList.toggle('is-visible',Boolean(message))};
    const openModal=(report,mode,trigger)=>{activeReport=report;opener=trigger;modal.hidden=false;modal.removeAttribute('inert');document.body.style.overflow='hidden';renderModal(mode);requestAnimationFrame(()=>closeButton.focus())};
    const closeModal=()=>{opener?.focus();modal.setAttribute('inert','');modal.hidden=true;document.body.style.overflow='';activeReport=null};
    closeButton.addEventListener('click',closeModal);modal.addEventListener('click',event=>{if(event.target===modal)closeModal()});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!modal.hidden)closeModal()});
    const renderModal=mode=>{
        eyebrow.textContent=reportName(activeReport);title.textContent=mode==='edit'?'Edit report':mode==='delete'?'Delete report':mode==='approve'?'Approve report':mode==='reject'?(activeReport.type==='aar'?'Request changes':'Reject report'):'Report details';
        if(mode==='view'){
            const base=[['Report type',reportName(activeReport)],['Incident',activeReport.incident_title],['Investigator',activeReport.investigator],['Report status',activeReport.status],['Approval status',reviewLabel(activeReport)],['Reviewed by',activeReport.reviewed_by_name],['Reviewed at',activeReport.reviewed_at],['Review comments',activeReport.review_comments],['Filed',activeReport.created_at]];
            const fields=fieldSets[activeReport.type].map(key=>[labels[key]||key,activeReport.fields?.[key]]);
            body.innerHTML=`<div class="report-detail-grid">${[...base,...fields].map(([label,value])=>`<div class="report-detail ${longFields.has(Object.keys(labels).find(key=>labels[key]===label))?'report-detail--wide':''}"><span>${escapeHtml(label)}</span><strong>${escapeHtml(displayValue(value))}</strong></div>`).join('')}</div>`;
            footer.innerHTML=`<button type="button" class="report-button report-button--ghost" data-modal-close>Close</button><a class="report-button report-button--primary" href="${downloadUrl(activeReport)}"><i class="fa-solid ${activeReport.type==='aar'?'fa-file-pdf':'fa-file-word'}"></i> Download ${activeReport.type==='aar'?'PDF':'Word'}</a>`;
        }else if(mode==='edit'){
            body.innerHTML=`<div id="executiveReportModalError" class="report-modal__error" role="alert"></div><form id="executiveReportEditForm" class="report-edit-grid">${fieldSets[activeReport.type].map(key=>renderField(key,activeReport.fields?.[key])).join('')}</form>`;
            footer.innerHTML='<button type="button" class="report-button report-button--ghost" data-modal-close>Cancel</button><button type="submit" form="executiveReportEditForm" class="report-button report-button--primary"><i class="fa-solid fa-check"></i> Save changes</button>';
            document.getElementById('executiveReportEditForm').addEventListener('submit',saveReport);
        }else if(mode==='approve'||mode==='reject'){
            const isReject=mode==='reject';
            const reviewCopy=isReject?(activeReport.type==='aar'?'Request changes and send comments back to the preparer.':'Reject this report and send comments back for revision.'):'Approve this report for command records.';
            body.innerHTML=`<div id="executiveReportModalError" class="report-modal__error" role="alert"></div><p class="report-modal__message"><strong>${escapeHtml(reportName(activeReport))}</strong><br>${reviewCopy}</p><div class="report-edit-field report-edit-field--wide" style="margin-top:14px;"><label for="executiveReviewComments">Review comments</label><textarea id="executiveReviewComments" placeholder="${isReject?'Describe what needs revision.':'Optional approval note.'}">${escapeHtml(activeReport.review_comments||'')}</textarea></div>${activeReport.type==='aar'&&!isReject?`<div class="report-edit-field report-edit-field--wide" style="margin-top:14px;"><label for="executiveSignatureName">Electronic signature</label><input id="executiveSignatureName" value="${escapeHtml(reviewerName)}"><label style="display:flex;gap:.65rem;align-items:flex-start;margin-top:.7rem;text-transform:none;letter-spacing:0;font-size:.78rem;font-weight:700"><input id="executiveSignatureConsent" type="checkbox" checked> <span>I adopt my typed name as my electronic signature.</span></label></div>`:''}`;
            footer.innerHTML=`<button type="button" class="report-button report-button--ghost" data-modal-close>Cancel</button><button type="button" class="report-button report-button--primary" data-confirm-review="${isReject?'rejected':'approved'}"><i class="fa-solid ${isReject?'fa-xmark':'fa-check'}"></i> ${isReject?(activeReport.type==='aar'?'Request changes':'Reject report'):'Approve report'}</button>`;
            footer.querySelector('[data-confirm-review]').addEventListener('click',event=>reviewReport(event.currentTarget.dataset.confirmReview));
        }else{
            body.innerHTML=`<div id="executiveReportModalError" class="report-modal__error" role="alert"></div><p class="report-modal__message"><strong>${escapeHtml(reportName(activeReport))}</strong><br>This permanently removes the report. Existing dependency rules may prevent deletion when a later investigation report is linked.</p>`;
            footer.innerHTML='<button type="button" class="report-button report-button--ghost" data-modal-close>Cancel</button><button type="button" class="report-button report-button--primary" data-confirm-delete><i class="fa-solid fa-trash-can"></i> Delete report</button>';
            footer.querySelector('[data-confirm-delete]').addEventListener('click',deleteReport);
        }
        footer.querySelector('[data-modal-close]')?.addEventListener('click',closeModal);
    };
    const renderField=(key,value)=>{
        const wide=longFields.has(key)?' report-edit-field--wide':'',required=requiredFields.has(key)?' required':'';
        if(key==='occupancy')return `<div class="report-edit-field${wide}"><label for="edit_${key}">${labels[key]}</label><select id="edit_${key}" name="${key}"${required}><option value="residential" ${value==='residential'?'selected':''}>Residential</option><option value="commercial" ${value==='commercial'?'selected':''}>Commercial</option><option value="industrial" ${value==='industrial'?'selected':''}>Industrial</option></select></div>`;
        if(key==='highest_alarm_level')return `<div class="report-edit-field${wide}"><label for="edit_${key}">${labels[key]}</label><select id="edit_${key}" name="${key}"><option value="">Not recorded</option>${['1st Alarm','2nd Alarm','3rd Alarm','4th Alarm','5th Alarm'].map(option=>`<option ${value===option?'selected':''}>${option}</option>`).join('')}</select></div>`;
        if(longFields.has(key))return `<div class="report-edit-field${wide}"><label for="edit_${key}">${labels[key]}</label><textarea id="edit_${key}" name="${key}"${required}>${escapeHtml(value??'')}</textarea></div>`;
        const type=dateFields.has(key)?'date':dateTimeFields.has(key)?'datetime-local':numberFields.has(key)?'number':'text',step=['estimated_damage','estimated_area','total_damage'].includes(key)?' step="0.01"':'',min=numberFields.has(key)?' min="0"':'';
        return `<div class="report-edit-field${wide}"><label for="edit_${key}">${labels[key]}</label><input id="edit_${key}" name="${key}" type="${type}" value="${escapeHtml(inputValue(value,type))}"${step}${min}${required}></div>`;
    };
    const requestReport=async(method)=>{const options={method,headers:{Accept:'application/json','X-CSRF-TOKEN':csrf,'X-Requested-With':'XMLHttpRequest'}};if(method==='PUT'){const form=new FormData(document.getElementById('executiveReportEditForm')),payload={};form.forEach((value,key)=>payload[key]=value===''?null:value);options.headers['Content-Type']='application/json';options.body=JSON.stringify(payload)}const response=await fetch(`/api/managements/reports/${activeReport.type}/${activeReport.id}`,options),data=await response.json().catch(()=>({}));if(!response.ok){const validation=data.errors?Object.values(data.errors).flat().join(' '):null;throw new Error(validation||data.message||'The report could not be updated.')}return data};
    const setBusy=busy=>footer.querySelectorAll('button').forEach(button=>button.disabled=busy);
    const saveReport=async event=>{event.preventDefault();setError('');setBusy(true);try{await requestReport('PUT');closeModal();await refreshReportPage()}catch(error){setError(error.message)}finally{setBusy(false)}};
    const deleteReport=async()=>{setError('');setBusy(true);try{await requestReport('DELETE');closeModal();await refreshReportPage()}catch(error){setError(error.message)}finally{setBusy(false)}};
    const reviewReport=async decision=>{setError('');setBusy(true);try{const comments=document.getElementById('executiveReviewComments')?.value||'';const isAar=activeReport.type==='aar';const endpoint=isAar?activeReport.review_url:`/api/managements/reports/${activeReport.type}/${activeReport.id}/review`;const payload=isAar?{decision:decision==='approved'?'approve':'request_changes',review_comments:comments,signature_name:document.getElementById('executiveSignatureName')?.value||reviewerName,signature_consent:document.getElementById('executiveSignatureConsent')?.checked?'1':''}:{decision,review_comments:comments};const response=await fetch(endpoint,{method:'PATCH',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':csrf,'X-Requested-With':'XMLHttpRequest'},body:JSON.stringify(payload)}),data=await response.json().catch(()=>({}));if(!response.ok){const validation=data.errors?Object.values(data.errors).flat().join(' '):null;throw new Error(validation||data.message||'The report review could not be saved.')}closeModal();await refreshReportPage()}catch(error){setError(error.message)}finally{setBusy(false)}};
    const refreshReportPage=async()=>{const response=await fetch(window.location.href,{headers:{'X-Requested-With':'XMLHttpRequest'}});if(!response.ok)throw new Error('The report list could not be refreshed.');const documentCopy=new DOMParser().parseFromString(await response.text(),'text/html');for(const selector of ['.report-stats','#reportResults']){const current=document.querySelector(selector),replacement=documentCopy.querySelector(selector);if(current&&replacement)current.replaceWith(replacement)}bindResults()};
    const reportPayloads=()=>{try{return JSON.parse(document.getElementById('executiveReportPayloads')?.textContent||'{}')}catch(error){console.error('Invalid executive report payload store.',error);return{}}};
    const bindResults=()=>{
        document.querySelectorAll('[data-report-action]').forEach(button=>button.addEventListener('click',()=>{try{const report=reportPayloads()[button.dataset.reportKey];if(!report){throw new Error(`Missing report payload: ${button.dataset.reportKey}`)}openModal(report,button.dataset.reportAction,button)}catch(error){console.error('Invalid report payload.',error)}}));
        document.querySelector('[data-report-print]')?.addEventListener('click',()=>window.print());
        document.querySelector('[data-report-csv]')?.addEventListener('click',()=>{const table=document.getElementById('executiveReportTable');if(!table)return;const csv=[...table.rows].map(row=>[...row.cells].filter(cell=>cell.cellIndex<row.cells.length-1).map(cell=>'"'+cell.innerText.replaceAll('"','""').replaceAll('\n',' · ')+'"').join(',')).join('\n'),blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='{{ $reportType }}_executive_reports_page_{{ $reportRows->currentPage() }}.csv';link.click();URL.revokeObjectURL(url)});
    };
    bindResults();
});
</script>
<script>document.addEventListener('DOMContentLoaded',()=>{const button=document.getElementById('userDropdownBtn'),menu=document.getElementById('userDropdownMenu');if(!button||!menu)return;button.addEventListener('click',event=>{event.stopPropagation();const open=menu.classList.toggle('show');button.setAttribute('aria-expanded',open?'true':'false')});document.addEventListener('click',event=>{if(!button.contains(event.target)&&!menu.contains(event.target)){menu.classList.remove('show');button.setAttribute('aria-expanded','false')}})});</script>
</body></html>
